export const workerSource = "// Worker template: `/slug <args>` starts a separate `pi --print` run, waits, posts one message.\n// Generated from agent.json and worker.json; flags come from the exporter's tool registry.\nimport type { ExtensionAPI, ExtensionCommandContext } from '@earendil-works/pi-coding-agent';\nimport { spawn, type ChildProcess } from 'node:child_process';\nimport { mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';\nimport { homedir } from 'node:os';\nimport { dirname, extname, join, relative, resolve, sep } from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\ninterface Input {\n  name: string;\n  label: string;\n  type: 'folder' | 'file' | 'text' | 'connection';\n  formats: string[];\n  required: boolean;\n}\ninterface Spec {\n  slug: string;\n  name: string;\n  description: string;\n  inputs: Input[];\n  conversation: 'oneShot' | 'followUp';\n  output: { kind: string; destination: string };\n}\ninterface WorkerConfig {\n  tools: string[];\n  extensions: string[];\n}\n\nexport function tokenize(text: string): string[] {\n  const tokens: string[] = [];\n  let current = '';\n  let quote = '';\n  let started = false;\n  for (const char of text) {\n    if (quote) {\n      if (char === quote) quote = '';\n      else current += char;\n    } else if (char === '\"' || char === \"'\") {\n      quote = char;\n      started = true;\n    } else if (/\\s/.test(char)) {\n      if (started) tokens.push(current);\n      current = '';\n      started = false;\n    } else {\n      current += char;\n      started = true;\n    }\n  }\n  if (started) tokens.push(current);\n  return tokens;\n}\n\nexport function usage(spec: Spec): string {\n  const args = spec.inputs.map((input) => (input.required ? '<' + input.name + '>' : '[' + input.name + ']'));\n  const lines = spec.inputs.map(\n    (input) =>\n      '  ' + input.name + ' (' + input.type + (input.formats.length ? ': ' + input.formats.join(', ') : '') + '): ' + input.label,\n  );\n  return ['Usage: /' + spec.slug + ' ' + args.join(' '), ...lines, 'Quote values that contain spaces. Use /' + spec.slug + ' cancel to stop.'].join('\\n');\n}\n\n/** Maps command arguments to declared inputs. The last text input takes the remaining words. */\nexport function parseInputs(spec: Spec, raw: string, cwd: string): { values: Record<string, string> } | { error: string } {\n  const tokens = tokenize(raw);\n  const values: Record<string, string> = {};\n  let index = 0;\n  spec.inputs.forEach((input, position) => {\n    if (index >= tokens.length) return;\n    const rest = position === spec.inputs.length - 1 && input.type === 'text';\n    values[input.name] = rest ? tokens.slice(index).join(' ') : tokens[index];\n    index = rest ? tokens.length : index + 1;\n  });\n  if (index < tokens.length) return { error: 'Too many arguments.\\n' + usage(spec) };\n  for (const input of spec.inputs) {\n    const value = values[input.name];\n    if (!value) {\n      if (input.required) return { error: 'Missing ' + input.name + '.\\n' + usage(spec) };\n      continue;\n    }\n    if (input.type !== 'file' && input.type !== 'folder') continue;\n    const path = resolve(cwd, value);\n    let kind: 'file' | 'folder' | undefined;\n    try {\n      const stats = statSync(path);\n      kind = stats.isDirectory() ? 'folder' : stats.isFile() ? 'file' : undefined;\n    } catch {\n      return { error: input.name + ' not found: ' + value };\n    }\n    if (kind !== input.type) return { error: input.name + ' must be a ' + input.type + ': ' + value };\n    const extension = extname(path).slice(1).toLowerCase();\n    if (input.type === 'file' && input.formats.length && !input.formats.includes(extension))\n      return { error: input.name + ' must be one of: ' + input.formats.join(', ') };\n    values[input.name] = path;\n  }\n  return { values };\n}\n\nexport default function (pi: ExtensionAPI) {\n  const spec = JSON.parse(readFileSync(new URL('../agent.json', import.meta.url), 'utf8')) as Spec;\n  const config = JSON.parse(readFileSync(new URL('../worker.json', import.meta.url), 'utf8')) as WorkerConfig;\n  const instructions = fileURLToPath(new URL('../instructions.md', import.meta.url));\n  const sessions = join(homedir(), '.pi', 'agent', 'agent-workers', spec.slug);\n  let child: ChildProcess | undefined;\n  let generation = 0;\n  let cancel: (() => void) | undefined;\n  pi.on('session_shutdown', async () => {\n    generation++;\n    cancel?.();\n  });\n  pi.registerCommand(spec.slug, {\n    description: spec.description + ' (cancel stops a run)',\n    handler: async (raw: string, ctx: ExtensionCommandContext) => {\n      const command = raw.trim();\n      if (command === 'cancel') {\n        cancel?.();\n        return;\n      }\n      if (command === 'help') {\n        ctx.ui.notify(usage(spec), 'info');\n        return;\n      }\n      if (command === 'reset' && spec.conversation === 'followUp') {\n        rmSync(sessions, { recursive: true, force: true });\n        ctx.ui.notify(spec.name + ' will start a new conversation next run.', 'info');\n        return;\n      }\n      if (child) {\n        ctx.ui.notify('Already running. Use /' + spec.slug + ' cancel.', 'warning');\n        return;\n      }\n      // Missing or invalid inputs get a usage reply without starting a model run.\n      const parsed = parseInputs(spec, command, ctx.cwd);\n      if ('error' in parsed) {\n        ctx.ui.notify(parsed.error, 'warning');\n        return;\n      }\n      // Read-only worker: no shell, writes, app connections or inherited extensions.\n      const args = ['--print', '--no-extensions', '--no-mcp', '--no-skills', '--no-prompt-templates', '--no-context-files', '--no-approve', '--system-prompt', instructions];\n      args.push(...(spec.conversation === 'followUp' ? ['--session-dir', sessions, '--continue'] : ['--no-session']));\n      for (const extension of config.extensions) args.push('--extension', fileURLToPath(new URL('../' + extension, import.meta.url)));\n      args.push(...(config.tools.length ? ['--tools', config.tools.join(',')] : ['--no-tools']));\n      if (ctx.model) args.push('--provider', ctx.model.provider, '--model', ctx.model.id);\n      if (spec.conversation === 'followUp') mkdirSync(sessions, { recursive: true });\n      const worker = spawn('pi', args, { cwd: ctx.cwd, stdio: ['pipe', 'pipe', 'pipe'], shell: false });\n      child = worker;\n      const runGeneration = generation;\n      let output = '';\n      let errors = '';\n      let failure = '';\n      let finished = false;\n      let killTimer: ReturnType<typeof setTimeout> | undefined;\n      const stop = () => {\n        worker.kill('SIGTERM');\n        killTimer ??= setTimeout(() => worker.kill('SIGKILL'), 2000);\n        killTimer.unref?.();\n      };\n      cancel = () => {\n        failure = 'Worker cancelled.';\n        stop();\n      };\n      const timer = setTimeout(() => {\n        failure = 'Worker timed out after 5 minutes.';\n        stop();\n      }, 300000);\n      const deliver = (text: string) => {\n        if (spec.output.kind !== 'file') return text;\n        const root = resolve(ctx.cwd);\n        const target = resolve(root, spec.output.destination);\n        if (!target.startsWith(root + sep)) return 'Refused to write outside the working directory.\\n\\n' + text;\n        mkdirSync(dirname(target), { recursive: true });\n        writeFileSync(target, text);\n        return 'Saved the result to ' + relative(root, target) + '.';\n      };\n      const finish = (error?: string) => {\n        if (finished) return;\n        finished = true;\n        clearTimeout(timer);\n        if (killTimer) clearTimeout(killTimer);\n        child = undefined;\n        cancel = undefined;\n        if (generation !== runGeneration) return;\n        ctx.ui.setStatus(spec.slug, undefined);\n        let content = error || output || 'Worker returned no output.';\n        if (!error && output) {\n          try {\n            content = deliver(output);\n          } catch (writeError) {\n            content = 'Could not save the result: ' + (writeError as Error).message + '\\n\\n' + output;\n          }\n        }\n        pi.sendMessage({ customType: 'agent-result', content, display: true }, { triggerTurn: false });\n      };\n      worker.stdout?.on('data', (chunk: Buffer) => {\n        if (output.length + chunk.length > 1000000) {\n          failure = 'Worker output exceeded 1 MB.';\n          stop();\n        } else output += chunk.toString();\n      });\n      worker.stderr?.on('data', (chunk: Buffer) => {\n        errors = (errors + chunk.toString()).slice(-4000);\n      });\n      worker.on('error', (error) => finish('Could not start pi: ' + error.message));\n      worker.on('close', (code) => finish(failure || (code === 0 ? undefined : 'Worker failed: ' + errors)));\n      worker.stdin?.on('error', () => {\n        /* Process errors are reported by close/error. */\n      });\n      // stdin keeps user text out of CLI option, slash-command and @file parsing.\n      const lines = spec.inputs\n        .filter((input) => parsed.values[input.name])\n        .map((input) => '- ' + input.name + ' (' + input.type + '): ' + parsed.values[input.name]);\n      worker.stdin?.end('Complete this task using your agent instructions.\\n\\nInputs:\\n' + lines.join('\\n') + '\\n');\n      ctx.ui.setStatus(spec.slug, 'Working: ' + spec.name);\n      ctx.ui.notify(spec.name + ' is working in the background (read-only).', 'info');\n    },\n  });\n}\n";
export const extensionSource = "// Extension template: starts on session_start and shows live state until session_shutdown.\n// Data sources come from agent.json: session-events, process-list and files:<path>.\nimport type { ExtensionAPI, ExtensionContext } from '@earendil-works/pi-coding-agent';\nimport { spawn, type ChildProcess } from 'node:child_process';\nimport { closeSync, mkdirSync, openSync, readdirSync, readFileSync, readSync, rmSync, statSync, writeFileSync } from 'node:fs';\nimport { tmpdir } from 'node:os';\nimport { basename, join, resolve } from 'node:path';\n\ninterface Spec {\n  slug: string;\n  name: string;\n  description: string;\n  dataSources: string[];\n  output: { kind: 'widget' | 'status' | string };\n}\ninterface Peer {\n  pid: number;\n  cwd: string;\n  activity: string;\n  tool: string;\n  toolCalls: number;\n  updatedAt: number;\n}\nconst REFRESH_MS = 5000;\nconst STALE_MS = 60000;\nconst AGENT_COMMANDS = /^(?:pi|claude|codex|cursor-agent|aider|gemini|opencode|goose|amp|crush|qwen)$/;\n\n/** Parses `ps -axo pid=,etime=,args=` and keeps known agent CLIs (direct or run through node/bun). */\nexport function parseProcesses(text: string, ownPid: number): string[] {\n  const rows: string[] = [];\n  for (const line of text.split('\\n')) {\n    const match = line.trim().match(/^(\\d+)\\s+(\\S+)\\s+(.+)$/);\n    if (!match || Number(match[1]) === ownPid) continue;\n    const [, pid, elapsed, args] = match;\n    const words = args.split(/\\s+/);\n    const first = basename(words[0]);\n    const second = basename(words[1] || '');\n    const agent = AGENT_COMMANDS.test(first) ? first : /^(?:node|bun|deno)$/.test(first) && AGENT_COMMANDS.test(second) ? second : undefined;\n    if (agent) rows.push(pid.padStart(6) + '  ' + elapsed.padStart(11) + '  ' + agent + ' ' + words.slice(agent === first ? 1 : 2).join(' ').slice(0, 60));\n  }\n  return rows.slice(0, 20);\n}\n\nexport function tail(path: string, lines = 5): string[] {\n  const size = statSync(path).size;\n  const length = Math.min(size, 65536);\n  const buffer = Buffer.alloc(length);\n  const fd = openSync(path, 'r');\n  try {\n    readSync(fd, buffer, 0, length, size - length);\n  } finally {\n    closeSync(fd);\n  }\n  return buffer.toString('utf8').split('\\n').filter(Boolean).slice(-lines);\n}\n\nexport default function (pi: ExtensionAPI) {\n  const spec = JSON.parse(readFileSync(new URL('../agent.json', import.meta.url), 'utf8')) as Spec;\n  const sources = new Set(spec.dataSources);\n  const filePaths = spec.dataSources.filter((source) => source.startsWith('files:')).map((source) => source.slice(6));\n  const shared = join(tmpdir(), 'pi-agent-' + spec.slug);\n  const own = join(shared, process.pid + '.json');\n  const state = { activity: 'idle', tool: '', toolCalls: 0 };\n  let context: ExtensionContext | undefined;\n  let visible = true;\n  let timer: ReturnType<typeof setInterval> | undefined;\n  let scan: ChildProcess | undefined;\n  let processes: string[] = [];\n  let peers: Peer[] = [];\n  let files: string[] = [];\n\n  const heartbeat = () => {\n    if (!sources.has('session-events') || !context) return;\n    try {\n      mkdirSync(shared, { recursive: true });\n      writeFileSync(own, JSON.stringify({ pid: process.pid, cwd: context.cwd, ...state, updatedAt: Date.now() }));\n    } catch {\n      /* Shared state is best effort; the local view still works. */\n    }\n  };\n  const readPeers = () => {\n    if (!sources.has('session-events')) return;\n    const now = Date.now();\n    const next: Peer[] = [];\n    let entries: string[] = [];\n    try {\n      entries = readdirSync(shared);\n    } catch {\n      entries = [];\n    }\n    for (const entry of entries) {\n      try {\n        const peer = JSON.parse(readFileSync(join(shared, entry), 'utf8')) as Peer;\n        if (now - peer.updatedAt < STALE_MS) next.push(peer);\n      } catch {\n        /* Skip files another session is writing. */\n      }\n    }\n    peers = next.sort((a, b) => a.pid - b.pid);\n  };\n  const scanProcesses = () => {\n    if (!sources.has('process-list') || scan || process.platform === 'win32') return;\n    let text = '';\n    const child = spawn('ps', ['-axo', 'pid=,etime=,args='], { shell: false, stdio: ['ignore', 'pipe', 'ignore'] });\n    scan = child;\n    const kill = setTimeout(() => child.kill('SIGKILL'), 4000);\n    child.stdout?.on('data', (chunk: Buffer) => {\n      if (text.length < 1000000) text += chunk.toString();\n    });\n    child.on('error', () => {\n      clearTimeout(kill);\n      scan = undefined;\n    });\n    child.on('close', () => {\n      clearTimeout(kill);\n      scan = undefined;\n      processes = parseProcesses(text, process.pid);\n      render();\n    });\n  };\n  const readFiles = () => {\n    if (!context) return;\n    const next: string[] = [];\n    for (const path of filePaths) {\n      const target = resolve(context.cwd, path);\n      try {\n        const stats = statSync(target);\n        if (stats.isDirectory()) next.push(path + ': ' + readdirSync(target).length + ' entries');\n        else next.push(path + ':', ...tail(target).map((line) => '  ' + line.slice(0, 100)));\n      } catch {\n        next.push(path + ': not found');\n      }\n    }\n    files = next;\n  };\n  const summary = () => {\n    const parts: string[] = [];\n    if (sources.has('session-events')) parts.push(peers.filter((peer) => peer.activity === 'working').length + '/' + peers.length + ' sessions working');\n    if (sources.has('process-list')) parts.push(processes.length + ' agent processes');\n    if (filePaths.length) parts.push(filePaths.length + ' files watched');\n    return spec.name + ': ' + (parts.join(' · ') || 'no data sources');\n  };\n  const lines = () => {\n    const out = [summary()];\n    if (sources.has('session-events'))\n      for (const peer of peers)\n        out.push((peer.pid === process.pid ? '* ' : '  ') + String(peer.pid).padStart(6) + '  ' + peer.activity.padEnd(7) + '  ' + (peer.tool || '-').padEnd(12) + '  ' + peer.toolCalls + ' tools  ' + basename(peer.cwd));\n    if (sources.has('process-list')) out.push(...(process.platform === 'win32' ? ['  Process list is not available on Windows.'] : processes.map((row) => '  ' + row)));\n    out.push(...files);\n    return out;\n  };\n  function render() {\n    if (!context?.hasUI) return;\n    if (!visible) {\n      context.ui.setWidget(spec.slug, undefined);\n      context.ui.setStatus(spec.slug, undefined);\n    } else if (spec.output.kind === 'status') context.ui.setStatus(spec.slug, summary());\n    else context.ui.setWidget(spec.slug, lines());\n  }\n  const refresh = () => {\n    heartbeat();\n    readPeers();\n    readFiles();\n    scanProcesses();\n    render();\n  };\n  const update = (patch: Partial<typeof state>) => {\n    Object.assign(state, patch);\n    refresh();\n  };\n\n  pi.on('session_start', async (_event, ctx) => {\n    context = ctx;\n    if (!timer) {\n      timer = setInterval(refresh, REFRESH_MS);\n      timer.unref?.();\n    }\n    refresh();\n  });\n  if (sources.has('session-events')) {\n    pi.on('agent_start', async () => update({ activity: 'working' }));\n    pi.on('agent_end', async () => update({ activity: 'idle', tool: '' }));\n    pi.on('tool_execution_start', async (event) => update({ tool: event.toolName, toolCalls: state.toolCalls + 1 }));\n    pi.on('tool_execution_end', async () => update({ tool: '' }));\n  }\n  pi.on('session_shutdown', async () => {\n    if (timer) clearInterval(timer);\n    timer = undefined;\n    scan?.kill('SIGKILL');\n    scan = undefined;\n    rmSync(own, { force: true });\n    if (context?.hasUI) {\n      context.ui.setWidget(spec.slug, undefined);\n      context.ui.setStatus(spec.slug, undefined);\n    }\n    context = undefined;\n  });\n  pi.registerCommand(spec.slug, {\n    description: spec.description + ' (no arguments toggles; show, hide, list)',\n    getArgumentCompletions: (prefix: string) =>\n      ['show', 'hide', 'list'].filter((value) => value.startsWith(prefix)).map((value) => ({ value, label: value })),\n    handler: async (raw: string, ctx) => {\n      context = ctx;\n      const command = raw.trim();\n      if (!command) visible = !visible;\n      else if (command === 'show') visible = true;\n      else if (command === 'hide') visible = false;\n      else if (command === 'list') {\n        refresh();\n        pi.sendMessage({ customType: 'agent-result', content: lines().join('\\n'), display: true }, { triggerTurn: false });\n        return;\n      } else {\n        ctx.ui.notify('Usage: /' + spec.slug + ' [show|hide|list]', 'warning');\n        return;\n      }\n      refresh();\n    },\n  });\n}\n";
export const calcSource = "// Bundled `calc` tool for analyze-data. A small arithmetic parser: no eval, no I/O.\nimport type { ExtensionAPI } from '@earendil-works/pi-coding-agent';\nimport { Type } from 'typebox';\n\nconst FUNCTIONS: Record<string, (...values: number[]) => number> = {\n  abs: Math.abs,\n  ceil: Math.ceil,\n  floor: Math.floor,\n  sqrt: Math.sqrt,\n  round: (value, digits = 0) => Math.round(value * 10 ** digits) / 10 ** digits,\n  min: Math.min,\n  max: Math.max,\n  sum: (...values) => values.reduce((total, value) => total + value, 0),\n  avg: (...values) => values.reduce((total, value) => total + value, 0) / values.length,\n  median: (...values) => {\n    const sorted = [...values].sort((a, b) => a - b);\n    const middle = Math.floor(sorted.length / 2);\n    return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;\n  },\n};\n\n/** Evaluates + - * / % ^, parentheses, percentages (12%) and the functions above. */\nexport function evaluate(expression: string): number {\n  if (expression.length > 2000) throw new Error('Expression is too long.');\n  const tokens = expression.match(/\\d+(?:\\.\\d+)?(?:e[+-]?\\d+)?|[a-z]+|\\*\\*|[-+*/%^(),]|\\S/gi) || [];\n  let position = 0;\n  const peek = () => tokens[position];\n  const take = (expected?: string) => {\n    const token = tokens[position++];\n    if (expected && token !== expected) throw new Error('Expected ' + expected + (token ? ' but found ' + token : ''));\n    return token;\n  };\n  const primary = (): number => {\n    const token = take();\n    if (token === undefined) throw new Error('Unexpected end of expression.');\n    if (token === '(') {\n      const value = sum();\n      take(')');\n      return value;\n    }\n    if (token === '-') return -power();\n    if (token === '+') return power();\n    if (/^\\d/.test(token)) {\n      const value = Number(token);\n      if (peek() === '%' && !/^[\\d(a-z]/i.test(tokens[position + 1] || '')) {\n        position++;\n        return value / 100;\n      }\n      return value;\n    }\n    const fn = FUNCTIONS[token.toLowerCase()];\n    if (fn) {\n      take('(');\n      const args = [sum()];\n      while (peek() === ',') {\n        take(',');\n        args.push(sum());\n      }\n      take(')');\n      return fn(...args);\n    }\n    throw new Error('Unknown token: ' + token);\n  };\n  const power = (): number => {\n    const base = primary();\n    if (peek() === '^' || peek() === '**') {\n      take();\n      return base ** power();\n    }\n    return base;\n  };\n  const product = (): number => {\n    let value = power();\n    while (peek() === '*' || peek() === '/' || peek() === '%') {\n      const operator = take();\n      const right = power();\n      if (operator === '*') value *= right;\n      else if (right === 0) throw new Error('Division by zero.');\n      else value = operator === '/' ? value / right : value % right;\n    }\n    return value;\n  };\n  const sum = (): number => {\n    let value = product();\n    while (peek() === '+' || peek() === '-') value = take() === '+' ? value + product() : value - product();\n    return value;\n  };\n  const result = sum();\n  if (position < tokens.length) throw new Error('Unexpected token: ' + tokens[position]);\n  if (!Number.isFinite(result)) throw new Error('Result is not a finite number.');\n  return result;\n}\n\nexport default function (pi: ExtensionAPI) {\n  pi.registerTool({\n    name: 'calc',\n    label: 'Calculate',\n    description:\n      'Evaluate arithmetic exactly. Supports + - * / % ^, parentheses, percentages (no thousands separators) and abs, ceil, floor, sqrt, round(x, digits), min, max, sum, avg, median. Use it for every number you report.',\n    parameters: Type.Object({\n      expressions: Type.Array(Type.String({ maxLength: 2000 }), { minItems: 1, maxItems: 50 }),\n    }),\n    annotations: { readOnlyHint: true, destructiveHint: false, openWorldHint: false },\n    async execute(_id, params) {\n      const results = params.expressions.map((expression) => {\n        try {\n          return { expression, value: evaluate(expression) };\n        } catch (error) {\n          return { expression, error: (error as Error).message };\n        }\n      });\n      const text = results.map((r) => r.expression + ' = ' + ('value' in r ? String(r.value) : 'error: ' + r.error)).join('\\n');\n      return { content: [{ type: 'text', text }], details: undefined };\n    },\n  });\n}\n";
export const extractSource = "// Bundled `extract_document` tool for extract-documents. Dependency-free, read-only text\n// extraction for PDF, DOCX, XLSX and PPTX. Scanned PDFs and unusual encodings return no text.\nimport type { ExtensionAPI } from '@earendil-works/pi-coding-agent';\nimport { readFileSync, statSync } from 'node:fs';\nimport { extname, resolve } from 'node:path';\nimport { inflateRawSync, inflateSync } from 'node:zlib';\nimport { Type } from 'typebox';\n\nconst MAX_BYTES = 25 * 1024 * 1024;\nconst MAX_ENTRY = 50 * 1024 * 1024;\n\n/** Reads stored and deflated entries from a ZIP archive (Office Open XML container). */\nexport function unzip(data: Buffer, wanted: (name: string) => boolean): Map<string, string> {\n  const files = new Map<string, string>();\n  let end = -1;\n  for (let i = data.length - 22; i >= Math.max(0, data.length - 65557); i--)\n    if (data.readUInt32LE(i) === 0x06054b50) {\n      end = i;\n      break;\n    }\n  if (end < 0) throw new Error('Not a valid Office document (ZIP directory missing).');\n  const count = data.readUInt16LE(end + 10);\n  let offset = data.readUInt32LE(end + 16);\n  for (let i = 0; i < count; i++) {\n    if (data.readUInt32LE(offset) !== 0x02014b50) throw new Error('Corrupt ZIP directory.');\n    const method = data.readUInt16LE(offset + 10);\n    const compressed = data.readUInt32LE(offset + 20);\n    const size = data.readUInt32LE(offset + 24);\n    const nameLength = data.readUInt16LE(offset + 28);\n    const extraLength = data.readUInt16LE(offset + 30);\n    const commentLength = data.readUInt16LE(offset + 32);\n    const local = data.readUInt32LE(offset + 42);\n    const name = data.toString('utf8', offset + 46, offset + 46 + nameLength);\n    offset += 46 + nameLength + extraLength + commentLength;\n    if (!wanted(name) || size > MAX_ENTRY) continue;\n    const start = local + 30 + data.readUInt16LE(local + 26) + data.readUInt16LE(local + 28);\n    const raw = data.subarray(start, start + compressed);\n    if (method === 0) files.set(name, raw.toString('utf8'));\n    else if (method === 8) files.set(name, inflateRawSync(raw, { maxOutputLength: MAX_ENTRY }).toString('utf8'));\n  }\n  return files;\n}\n\nconst decode = (text: string) =>\n  text\n    .replace(/&lt;/g, '<')\n    .replace(/&gt;/g, '>')\n    .replace(/&quot;/g, '\"')\n    .replace(/&apos;/g, \"'\")\n    .replace(/&#(\\d+);/g, (_, code: string) => String.fromCodePoint(Number(code)))\n    .replace(/&#x([0-9a-f]+);/gi, (_, code: string) => String.fromCodePoint(parseInt(code, 16)))\n    .replace(/&amp;/g, '&');\nconst byNumber = (a: string, b: string) => Number(a.match(/(\\d+)\\.xml$/)?.[1] || 0) - Number(b.match(/(\\d+)\\.xml$/)?.[1] || 0);\n\nfunction docx(data: Buffer) {\n  const xml = unzip(data, (name) => name === 'word/document.xml').get('word/document.xml') || '';\n  return decode(\n    xml\n      .replace(/<w:tab\\/>/g, '\\t')\n      .replace(/<w:br\\/>|<\\/w:p>/g, '\\n')\n      .replace(/<\\/w:tc>/g, '\\t')\n      .replace(/<[^>]+>/g, ''),\n  ).trim();\n}\n\nfunction columnIndex(reference: string) {\n  let index = 0;\n  for (const char of reference.replace(/\\d+/g, '')) index = index * 26 + char.charCodeAt(0) - 64;\n  return index - 1;\n}\nfunction xlsx(data: Buffer) {\n  const files = unzip(data, (name) => name === 'xl/sharedStrings.xml' || name === 'xl/workbook.xml' || /^xl\\/worksheets\\/sheet\\d+\\.xml$/.test(name));\n  const shared = [...(files.get('xl/sharedStrings.xml') || '').matchAll(/<si>([\\s\\S]*?)<\\/si>/g)].map((m) =>\n    decode([...m[1].matchAll(/<t[^>]*>([\\s\\S]*?)<\\/t>/g)].map((t) => t[1]).join('')),\n  );\n  const names = [...(files.get('xl/workbook.xml') || '').matchAll(/<sheet [^>]*name=\"([^\"]*)\"/g)].map((m) => decode(m[1]));\n  const sheets = [...files.keys()].filter((name) => name.startsWith('xl/worksheets/')).sort(byNumber);\n  return sheets\n    .map((name, index) => {\n      const rows = [...files.get(name)!.matchAll(/<row[^>]*>([\\s\\S]*?)<\\/row>/g)].map((row) => {\n        const cells: string[] = [];\n        for (const cell of row[1].matchAll(/<c ([^>]*?)(?:\\/>|>([\\s\\S]*?)<\\/c>)/g)) {\n          const attributes = cell[1];\n          const body = cell[2] || '';\n          const reference = attributes.match(/r=\"([A-Z]+\\d+)\"/)?.[1];\n          const type = attributes.match(/t=\"(\\w+)\"/)?.[1];\n          const value = body.match(/<v>([\\s\\S]*?)<\\/v>/)?.[1] ?? '';\n          const text =\n            type === 's' ? shared[Number(value)] ?? '' : type === 'inlineStr' ? decode([...body.matchAll(/<t[^>]*>([\\s\\S]*?)<\\/t>/g)].map((t) => t[1]).join('')) : decode(value);\n          cells[reference ? columnIndex(reference) : cells.length] = /[\",\\n]/.test(text) ? '\"' + text.replace(/\"/g, '\"\"') + '\"' : text;\n        }\n        return Array.from(cells, (cell) => cell ?? '').join(',');\n      });\n      return '# Sheet: ' + (names[index] || name) + '\\n' + rows.join('\\n');\n    })\n    .join('\\n\\n')\n    .trim();\n}\n\nfunction pptx(data: Buffer) {\n  const files = unzip(data, (name) => /^ppt\\/slides\\/slide\\d+\\.xml$/.test(name));\n  return [...files.keys()]\n    .sort(byNumber)\n    .map((name, index) => '# Slide ' + (index + 1) + '\\n' + [...files.get(name)!.matchAll(/<a:t>([\\s\\S]*?)<\\/a:t>/g)].map((m) => decode(m[1])).join('\\n'))\n    .join('\\n\\n')\n    .trim();\n}\n\nfunction pdfString(raw: string) {\n  return raw.replace(/\\\\([nrtbf()\\\\]|[0-7]{1,3})/g, (_, code: string) =>\n    /^[0-7]/.test(code) ? String.fromCharCode(parseInt(code, 8)) : ({ n: '\\n', r: '', t: '\\t', b: '', f: '' } as Record<string, string>)[code] ?? code,\n  );\n}\n/** Best-effort text from content streams (Tj, TJ, ' and \" operators). */\nexport function pdf(data: Buffer) {\n  const binary = data.toString('latin1');\n  const chunks: string[] = [];\n  for (const match of binary.matchAll(/<<([\\s\\S]*?)>>\\s*stream\\r?\\n/g)) {\n    const start = match.index! + match[0].length;\n    const end = binary.indexOf('endstream', start);\n    if (end < 0) continue;\n    const raw = data.subarray(start, end);\n    let content: string;\n    try {\n      content = /FlateDecode/.test(match[1]) ? inflateSync(raw, { maxOutputLength: MAX_ENTRY }).toString('latin1') : /\\/Filter/.test(match[1]) ? '' : raw.toString('latin1');\n    } catch {\n      continue;\n    }\n    for (const block of content.matchAll(/BT([\\s\\S]*?)ET/g)) {\n      let line = '';\n      for (const op of block[1].matchAll(/\\[((?:\\\\.|[^\\]])*)\\]\\s*TJ|\\(((?:\\\\.|[^\\\\)])*)\\)\\s*(?:Tj|'|\")|(T\\*|Td|TD|Tm)/g)) {\n        if (op[3]) {\n          if (line.trim()) chunks.push(line);\n          line = '';\n        } else if (op[2] !== undefined) line += pdfString(op[2]);\n        else\n          for (const part of op[1].matchAll(/\\(((?:\\\\.|[^\\\\)])*)\\)|(-?\\d+(?:\\.\\d+)?)/g))\n            if (part[1] !== undefined) line += pdfString(part[1]);\n            else if (Number(part[2]) < -200) line += ' ';\n      }\n      if (line.trim()) chunks.push(line);\n    }\n  }\n  return chunks.join('\\n').trim();\n}\n\nexport function extractText(path: string): string {\n  const format = extname(path).slice(1).toLowerCase();\n  if (statSync(path).size > MAX_BYTES) throw new Error('File is larger than 25 MB.');\n  const data = readFileSync(path);\n  const text = format === 'pdf' ? pdf(data) : format === 'docx' ? docx(data) : format === 'xlsx' ? xlsx(data) : format === 'pptx' ? pptx(data) : undefined;\n  if (text === undefined) throw new Error('Unsupported format: ' + (format || 'none') + '. Use read for text files.');\n  if (!text) throw new Error('No extractable text. The file may be scanned or use an unsupported encoding; ask for a text or CSV export.');\n  return text;\n}\n\nexport default function (pi: ExtensionAPI) {\n  pi.registerTool({\n    name: 'extract_document',\n    label: 'Extract document',\n    description: 'Extract plain text from a PDF, DOCX, XLSX (as CSV per sheet) or PPTX file. Read-only.',\n    parameters: Type.Object({\n      path: Type.String({ description: 'File path, relative to the working directory' }),\n      offset: Type.Optional(Type.Integer({ minimum: 0, description: 'Character offset for long documents' })),\n    }),\n    annotations: { readOnlyHint: true, destructiveHint: false, openWorldHint: false },\n    async execute(_id, params, _signal, _onUpdate, ctx) {\n      const text = extractText(resolve(ctx.cwd, params.path));\n      const offset = params.offset ?? 0;\n      const page = text.slice(offset, offset + 50000);\n      const more = offset + page.length < text.length ? '\\n\\n[Truncated. Continue with offset ' + (offset + page.length) + ' of ' + text.length + '.]' : '';\n      return { content: [{ type: 'text', text: page + more }], details: undefined };\n    },\n  });\n}\n";
